 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            boxes.append((min(x for x,y in cells), max(x for x,y in cells),
                          min(y for x,y in cells), max(y for x,y in cells)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # Embedded 2s are missing cells inside a 3-filled rectangular field;
            # unrelated 2s outside those bounds are distractors.
            if not any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes):
                continue
            for rr in range(max(0, r-1), min(h, r+2)):
                for cc in range(max(0, c-1), min(w, c+2)):
                    if grid[rr][cc] != 2:
                        out[rr][cc] = 1
    return out
